import {
  Body,
  Container,
  Head as EmailHead,
  Html,
  Img,
  Preview,
  Section,
  Row,
  Column,
  Heading,
  Text,
  Link,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type CardCouponsVariant =
  | "with-name"
  | "with-pattern"
  | "with-overlay"
  | "with-background-image"
  | "background-image-header";

export interface CardCouponsProps {
  theme?: EmailTheme;
  heading?: string;
  recipient?: string;
  code?: string;
  description?: string;
  logoSrc?: string;
  logoAlt?: string;
  backgroundImageSrc?: string;
  buttonLabel?: string;
  buttonHref?: string;
  arrowIconSrc?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  cardBackgroundColor?: string;
  codeBackgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  mutedTextColor?: string;
  buttonBackgroundColor?: string;
  buttonColor?: string;
  variant?: CardCouponsVariant;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = `
  @media only screen and (max-width: 599px) {
    .coupon-card-logo { width: 88px !important; }
    .coupon-card-heading { font-size: 20px !important; line-height: 28px !important; }
    .coupon-card-description { padding-left: 24px !important; padding-right: 24px !important; }
    .coupon-card-name-pad { padding-top: 32px !important; padding-bottom: 32px !important; }
    .coupon-card-edge-spacer { line-height: 16px !important; }
  }

  @media only screen and (max-width: 430px) {
    .coupon-card-shell { padding-left: 24px !important; padding-right: 24px !important; }
  }
`;

const sharedDefaults = {
  arrowIconSrc: emailAsset("icon-arrow-right.png"),
  backgroundColor: "#fffffe",
  buttonBackgroundColor: "#4f46e5",
  buttonColor: "#fffffe",
  buttonHref: "https://example.com",
  buttonLabel: "Shop now",
  cardBackgroundColor: "#1f2937",
  code: "WINTER20OFF",
  codeBackgroundColor: "#f3f4f6",
  description:
    "Use code: WINTER20OFF at checkout, or click the link below to automatically apply the discount to your order.",
  headingColor: "#fffffe",
  logoAlt: "Maizzle",
  mutedTextColor: "#9ca3af",
  pageBackgroundColor: "#f1f5f9",
  recipient: "Jenna Adams",
  textColor: "#4b5563",
};

const variantDefaults: Record<CardCouponsVariant, Partial<CardCouponsProps>> = {
  "background-image-header": {
    backgroundImageSrc: emailAsset("coupons/bg-image-3.jpg"),
    code: "JFY20OFF",
    heading: "Just for you - 20% OFF",
    logoSrc: emailAsset("maizzle-insignia-light-lg.png"),
  },
  "with-background-image": {
    backgroundImageSrc: emailAsset("coupons/bg-image-2.jpg"),
    heading: "An extra 20% OFF",
    logoSrc: emailAsset("maizzle-insignia-light-lg.png"),
  },
  "with-name": {
    cardBackgroundColor: "#030712",
    heading: "Just for you - 20% OFF",
    logoSrc: emailAsset("maizzle-insignia.png"),
  },
  "with-overlay": {
    backgroundImageSrc: emailAsset("coupons/bg-image-1.jpg"),
    cardBackgroundColor: "#030712",
    heading: "An extra 20% OFF",
    logoSrc: emailAsset("maizzle-insignia-light-lg.png"),
  },
  "with-pattern": {
    backgroundImageSrc: emailAsset("coupons/pattern.png"),
    heading: "An extra 20% OFF",
    logoSrc: emailAsset("maizzle-insignia-light-lg.png"),
  },
};

type SectionProps = Omit<CardCouponsProps, "theme">;

type ResolvedProps = typeof sharedDefaults & SectionProps;

const Logo = ({
  props,
  width = 100,
}: {
  props: ResolvedProps;
  width?: number;
}) => (
  <Img
    alt={props.logoAlt}
    className={width === 100 ? "coupon-card-logo" : undefined}
    src={props.logoSrc}
    style={{ display: "inline", maxWidth: "100%", verticalAlign: "middle" }}
    width={width}
  />
);

const getCodeBackgroundColor = ({
  dark,
  props,
  white,
}: {
  dark: boolean;
  props: ResolvedProps;
  white: boolean;
}) => {
  if (white) {
    return "#fffffe";
  }
  if (dark) {
    return props.cardBackgroundColor;
  }
  return props.codeBackgroundColor;
};

const CodeBox = ({
  dark = false,
  props,
  white = false,
}: {
  dark?: boolean;
  props: ResolvedProps;
  white?: boolean;
}) => (
  <Section align="center" style={{ margin: "0 auto" }}>
    <Fragment>
      <Row>
        <Column
          style={{
            backgroundColor: getCodeBackgroundColor({ dark, props, white }),
            border: dark ? "1px solid #374151" : undefined,
            borderRadius: "8px",
            color: white || !dark ? "#030712" : props.headingColor,
            fontFamily,
            fontSize: "16px",
            lineHeight: "24px",
            padding: "8px 16px",
          }}
        >
          {props.code}
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const OfferHeading = ({ props }: { props: ResolvedProps }) => (
  <Heading
    className="coupon-card-heading"
    style={{
      color: props.headingColor,
      fontFamily,
      fontSize: "24px",
      fontWeight: 600,
      lineHeight: "32px",
      margin: "36px 0 0",
      textAlign: "center",
    }}
    as="h3"
  >
    {props.heading}
  </Heading>
);

const StandardCardContent = ({
  codeStyle,
  props,
}: {
  codeStyle: "dark" | "white";
  props: ResolvedProps;
}) => (
  <>
    <Section className="coupon-card-edge-spacer" style={{ lineHeight: "28px" }}>
      &zwj;
    </Section>
    <Section style={{ textAlign: "center" }}>
      <Logo props={props} />
    </Section>
    <OfferHeading props={props} />
    <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
    <CodeBox
      dark={codeStyle === "dark"}
      props={props}
      white={codeStyle === "white"}
    />
    <Section className="coupon-card-edge-spacer" style={{ lineHeight: "28px" }}>
      &zwj;
    </Section>
  </>
);

const CouponCard = ({
  props,
  variant,
}: {
  props: ResolvedProps;
  variant: CardCouponsVariant;
}) => {
  if (variant === "with-name") {
    return (
      <Section width="100%">
        <Fragment>
          <Row>
            <Column
              className="coupon-card-name-pad"
              style={{
                backgroundColor: props.cardBackgroundColor,
                borderRadius: "8px",
                boxShadow: "0 25px 50px -12px rgba(0,0,0,0.25)",
                padding: "44px 10px",
                textAlign: "center",
              }}
            >
              <Logo props={props} />
              <OfferHeading props={props} />
              <Text
                style={{
                  color: props.mutedTextColor,
                  fontFamily,
                  fontSize: "16px",
                  lineHeight: "24px",
                  margin: "16px 0 0",
                }}
              >
                {props.recipient}
              </Text>
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  if (variant === "background-image-header") {
    return (
      <Section width="100%">
        <Fragment>
          <Row>
            <Column
              style={{
                backgroundColor: props.cardBackgroundColor,
                backgroundImage: `url('${props.backgroundImageSrc}')`,
                backgroundPosition: "center",
                backgroundRepeat: "no-repeat",
                backgroundSize: "cover",
                borderRadius: "8px",
                boxShadow: "0 25px 50px -12px rgba(0,0,0,0.25)",
              }}
            >
              <Section width="100%">
                <Fragment>
                  <Row>
                    <Column style={{ width: "10px" }}>&zwj;</Column>
                    <Column>
                      <Section style={{ lineHeight: "12px" }}>&zwj;</Section>
                      <Section width="100%">
                        <Fragment>
                          <Row>
                            <Column style={{ width: "50%" }}>
                              <Logo props={props} width={44} />
                            </Column>
                            <Column
                              style={{
                                color: props.headingColor,
                                fontFamily,
                                fontSize: "16px",
                                textAlign: "right",
                                width: "50%",
                              }}
                            >
                              {props.recipient}
                            </Column>
                          </Row>
                        </Fragment>
                      </Section>
                      <Heading
                        className="coupon-card-heading"
                        style={{
                          color: props.headingColor,
                          fontFamily,
                          fontSize: "24px",
                          fontWeight: 600,
                          lineHeight: "32px",
                          margin: "72px 0 0",
                          textAlign: "center",
                        }}
                        as="h3"
                      >
                        {props.heading}
                      </Heading>
                      <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
                      <CodeBox props={props} white />
                      <Section style={{ lineHeight: "28px" }}>&zwj;</Section>
                    </Column>
                    <Column style={{ width: "10px" }}>&zwj;</Column>
                  </Row>
                </Fragment>
              </Section>
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  const card = (
    <Column
      style={{
        backgroundColor: props.cardBackgroundColor,
        backgroundImage: `url('${props.backgroundImageSrc}')`,
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
        backgroundSize: "cover",
        borderRadius: "8px",
        boxShadow: "0 25px 50px -12px rgba(0,0,0,0.25)",
        padding: variant === "with-overlay" ? "12px 10px" : "0 10px",
      }}
    >
      {(() => {
        if (variant === "with-overlay") {
          return (
            <Section
              style={{
                background:
                  "linear-gradient(to bottom, transparent, rgba(3,7,18,0.6))",
                backgroundColor: "rgba(3,7,18,0.6)",
                borderRadius: "4px",
              }}
            >
              <StandardCardContent codeStyle="dark" props={props} />
            </Section>
          );
        }
        return (
          <StandardCardContent
            codeStyle={variant === "with-pattern" ? "dark" : "white"}
            props={props}
          />
        );
      })()}
    </Column>
  );
  return (
    <Section width="100%">
      <Fragment>
        <Row>{card}</Row>
      </Fragment>
    </Section>
  );
};

const Description = ({ props }: { props: ResolvedProps }) => (
  <Section width="100%">
    <Fragment>
      <Row>
        <Column
          className="coupon-card-description"
          style={{ padding: "0 44px" }}
        >
          <Text
            style={{
              color: props.textColor,
              fontFamily,
              fontSize: "16px",
              fontWeight: 300,
              lineHeight: "24px",
              margin: 0,
              textAlign: "center",
            }}
          >
            Use code: <strong>{props.code}</strong> at checkout, or click the
            link below to automatically apply the discount to your order.
          </Text>
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const CouponButton = ({ props }: { props: ResolvedProps }) => (
  <Section style={{ textAlign: "center" }}>
    <Link
      href={props.buttonHref}
      style={{
        backgroundColor: props.buttonBackgroundColor,
        borderRadius: "8px",
        color: props.buttonColor,
        display: "inline-block",
        fontFamily,
        fontSize: "16px",
        fontWeight: 500,
        lineHeight: 1,
        padding: "14px 20px",
        textDecoration: "none",
      }}
    >
      <span style={{ marginRight: "8px" }}>{props.buttonLabel}</span>
      <span>
        <Img
          alt=""
          src={props.arrowIconSrc}
          style={{
            display: "inline",
            maxWidth: "100%",
            verticalAlign: "baseline",
          }}
          width={12}
        />
      </span>
    </Link>
  </Section>
);

export const CardCouponsSection = (props: SectionProps) => {
  const variant = props.variant ?? "with-overlay";
  const resolved = {
    ...sharedDefaults,
    ...variantDefaults[variant],
    ...props,
  } as ResolvedProps;
  const showDescription =
    variant === "with-name" ||
    variant === "with-pattern" ||
    variant === "with-overlay";
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: resolved.backgroundColor,
              maxWidth: "100%",
              paddingBottom: "44px",
              width: "600px",
            }}
          >
            <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
            <Section align="center" style={{ margin: "0 auto" }}>
              <Fragment>
                <Row>
                  <Column style={{ maxWidth: "100%", width: "400px" }}>
                    <Section className="coupon-card-shell">
                      <CouponCard props={resolved} variant={variant} />
                    </Section>
                  </Column>
                </Row>
              </Fragment>
            </Section>
            {showDescription ? (
              <>
                <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
                <Description props={resolved} />
              </>
            ) : null}
            {variant === "with-name" ? (
              <>
                <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
                <CodeBox props={resolved} />
              </>
            ) : null}
            <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
            <CouponButton props={resolved} />
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const CardCoupons = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "with-overlay",
  ...props
}: CardCouponsProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: responsiveStyles }} />
    </EmailHead>
    <Preview>An extra 20% OFF</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{ backgroundColor: pageBackgroundColor, fontFamily }}
        className="m-0"
      >
        <Container className="mx-auto max-w-[600px] w-[600px]">
          <CardCouponsSection
            {...props}
            pageBackgroundColor={pageBackgroundColor}
            variant={variant}
          />
        </Container>
      </Body>
    </EmailTailwind>
  </Html>
);

CardCoupons.PreviewProps = {
  theme: defaultTheme,
  variant: "with-overlay",
} satisfies CardCouponsProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
